#!/usr/bin/env bash
set -euo pipefail

source scripts/lib/common.sh
load_hooks_env

msg_file="${1:-}"
if [[ -z "$msg_file" || ! -f "$msg_file" ]]; then
  echo "Usage: $0 <commit-message-file>" >&2
  exit 2
fi

msg="$(cat "$msg_file")"

if [[ -z "${msg//[[:space:]]/}" ]]; then
  echo "Commit message is empty." >&2
  exit 1
fi

# Ignore autogenerated merge/revert/fixup messages.
subject="$(head -n1 "$msg_file")"
if [[ "$subject" =~ ^Merge\  || "$subject" =~ ^Revert\  || "$subject" =~ ^fixup! || "$subject" =~ ^squash! ]]; then
  exit 0
fi

repo_slug="$(resolve_repo_slug || true)"
issue_url_regex="$(issue_url_regex_for_repo "$repo_slug")"

if ! grep -Eiq "^Issue:[[:space:]]*(#([0-9]+)|${issue_url_regex})[[:space:]]*$" "$msg_file"; then
  echo "Missing required issue link. Add: 'Issue: #123' or valid GitHub issue URL." >&2
  if [[ -n "${repo_slug:-}" && "${HOOKS_REQUIRE_SAME_REPO_URL:-1}" == "1" ]]; then
    echo "Expected same-repo URL pattern for ${repo_slug}." >&2
  fi
  exit 1
fi

if ! grep -Eiq '^Type:[[:space:]]*(feature|bugfix|refactor|docs|chore|security)[[:space:]]*$' "$msg_file"; then
  echo "Missing required change type. Add: 'Type: feature|bugfix|refactor|docs|chore|security'." >&2
  exit 1
fi
change_type="$(grep -Eio '^Type:[[:space:]]*(feature|bugfix|refactor|docs|chore|security)[[:space:]]*$' "$msg_file" | sed -E 's/^Type:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1)"

if ! grep -Eiq '^Risk:[[:space:]]*(low|medium|high)[[:space:]]*$' "$msg_file"; then
  echo "Missing required risk level. Add: 'Risk: low|medium|high'." >&2
  exit 1
fi
risk_level="$(grep -Eio '^Risk:[[:space:]]*(low|medium|high)[[:space:]]*$' "$msg_file" | sed -E 's/^Risk:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1)"

enforce_test_contract="${HOOKS_ENFORCE_TEST_CONTRACT:-1}"
enforce_stack_cmd_hints="${HOOKS_ENFORCE_STACK_COMMAND_HINTS:-1}"
require_high_risk_threat_model="${HOOKS_REQUIRE_HIGH_RISK_THREAT_MODEL:-1}"
require_high_risk_rollback_rehearsal="${HOOKS_REQUIRE_HIGH_RISK_ROLLBACK_REHEARSAL:-1}"
require_medium_high_quality_signals="${HOOKS_REQUIRE_MEDIUM_HIGH_QUALITY_SIGNALS:-1}"
require_security_trust_boundary="${HOOKS_REQUIRE_SECURITY_TRUST_BOUNDARY:-1}"
enforce_policy_exception_fields="${HOOKS_ENFORCE_POLICY_EXCEPTION_FIELDS:-1}"
require_review_passes="${HOOKS_REQUIRE_REVIEW_PASSES:-1}"
require_high_risk_review_packet="${HOOKS_REQUIRE_HIGH_RISK_REVIEW_PACKET:-1}"
require_dependency_check="${HOOKS_REQUIRE_DEPENDENCY_CHECK:-1}"
bugfix_high_context_file_threshold="${BUGFIX_HIGH_CONTEXT_FILE_THRESHOLD:-10}"
require_high_risk_second_review="${HOOKS_REQUIRE_HIGH_RISK_SECOND_REVIEW:-1}"
require_security_signoff="${HOOKS_REQUIRE_SECURITY_SIGNOFF:-1}"
reject_expired_policy_dates="${HOOKS_REJECT_EXPIRED_POLICY_DATES:-1}"
require_review_focus="${HOOKS_REQUIRE_REVIEW_FOCUS:-1}"
require_security_checklist="${HOOKS_REQUIRE_SECURITY_CHECKLIST:-1}"
require_security_scans_declaration="${HOOKS_REQUIRE_SECURITY_SCANS_DECLARATION:-1}"
require_performance_evidence="${HOOKS_REQUIRE_PERFORMANCE_EVIDENCE:-1}"
require_high_risk_performance_evidence="${HOOKS_REQUIRE_HIGH_RISK_PERFORMANCE_EVIDENCE:-1}"
require_maintainability_evidence="${HOOKS_REQUIRE_MAINTAINABILITY_EVIDENCE:-1}"
require_observability_evidence="${HOOKS_REQUIRE_OBSERVABILITY_EVIDENCE:-1}"
require_agent_role="${HOOKS_REQUIRE_AGENT_ROLE:-1}"
require_stack_profile="${HOOKS_REQUIRE_STACK_PROFILE:-1}"
require_self_eval="${HOOKS_REQUIRE_SELF_EVAL:-1}"
require_data_handling_declaration="${HOOKS_REQUIRE_DATA_HANDLING_DECLARATION:-1}"
require_release_safety_fields="${HOOKS_REQUIRE_RELEASE_SAFETY_FIELDS:-1}"
require_compatibility_fields="${HOOKS_REQUIRE_COMPATIBILITY_FIELDS:-1}"
require_dependency_license_check="${HOOKS_REQUIRE_DEPENDENCY_LICENSE_CHECK:-1}"
enforce_stack_map="${HOOKS_ENFORCE_STACK_MAP:-1}"
contract_compat_required_path_regex="${CONTRACT_COMPAT_REQUIRED_PATH_REGEX:-openapi|schema|contract|interface|api/}"
policy_update_path_regex="${POLICY_UPDATE_PATH_REGEX:-^AGENTS\\.md$|^docs/policy/|^docs/templates/|^scripts/(validate-|check-policy-stack|policy-drift-audit|install-git-hooks|hooks\\.env|lib/common\\.sh)}"
stack_name=""
test_scope_line=""
agent_role=""
dependency_manifest_regex='(^|/)(package\.json|package-lock\.json|pnpm-lock\.yaml|yarn\.lock|requirements(\.txt|-dev\.txt)?|pyproject\.toml|poetry\.lock|go\.mod|go\.sum|pom\.xml|build\.gradle(\.kts)?|gradle\.lockfile|Cargo\.toml|Cargo\.lock|Gemfile|Gemfile\.lock|composer\.json|composer\.lock)$'
today_ymd="$(date -u +%F 2>/dev/null || date +%F)"
policy_mode="${HOOKS_POLICY_MODE:-strict}"
staged_files_list="$(git diff --cached --name-only)"
stack_active_profiles="${STACK_ACTIVE_PROFILES:-node,python,go,java,dotnet,rust,php,ruby}"
detected_stacks=""

if [[ "$policy_mode" != "strict" && "$policy_mode" != "minimal" ]]; then
  echo "Invalid HOOKS_POLICY_MODE='${policy_mode}'. Allowed: strict|minimal." >&2
  exit 1
fi

if [[ "$policy_mode" == "minimal" ]]; then
  require_medium_high_quality_signals=0
  require_review_passes=0
  require_review_focus=0
  require_observability_evidence=0
  require_stack_profile=0
  require_performance_evidence=0
  require_high_risk_performance_evidence=0
  require_maintainability_evidence=0
  require_data_handling_declaration=0
  require_high_risk_review_packet=0
fi

load_stack_map
stack_active_profiles="${STACK_ACTIVE_PROFILES:-$stack_active_profiles}"
detected_stacks="$(detect_stacks_from_paths "$staged_files_list")"

if ! grep -Eq '^Verification:[[:space:]]*$' "$msg_file"; then
  echo "Missing required verification section. Add 'Verification:' with command/output lines." >&2
  exit 1
fi

if ! grep -Eq '^[[:space:]]*\$[[:space:]]+.+$' "$msg_file"; then
  echo "Verification must include at least one command line like '$ npm test'." >&2
  exit 1
fi

if ! grep -Eiq '^[[:space:]]*(Output|Observed|Expected):[[:space:]]+.+$' "$msg_file"; then
  echo "Verification must include at least one result line like 'Output: ...'." >&2
  exit 1
fi

if grep -Eiq '(^|[[:space:]])(TBD|N/A|not run|skip(ped)?)([[:space:]]|$)' "$msg_file"; then
  echo "Verification contains placeholder text (TBD/N/A/not run/skipped). Replace with real evidence." >&2
  exit 1
fi

if [[ "$enforce_test_contract" == "1" ]]; then
  if [[ "$change_type" =~ ^(feature|bugfix|refactor|security)$ ]]; then
    if ! grep -Eiq '^Stack:[[:space:]]*(node|python|go|java|dotnet|rust|php|ruby|polyglot|other)[[:space:]]*$' "$msg_file"; then
      echo "Code-impacting commit requires stack declaration." >&2
      echo "Add: 'Stack: node|python|go|java|dotnet|rust|php|ruby|polyglot|other'." >&2
      exit 1
    fi
    stack_name="$(grep -Eio '^Stack:[[:space:]]*(node|python|go|java|dotnet|rust|php|ruby|polyglot|other)[[:space:]]*$' "$msg_file" | sed -E 's/^Stack:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1)"

    if [[ "$enforce_stack_map" == "1" ]]; then
      if [[ "$stack_name" != "polyglot" && "$stack_name" != "other" ]]; then
        if ! csv_contains "$stack_active_profiles" "$stack_name"; then
          echo "Declared Stack '${stack_name}' is not active for this repo." >&2
          echo "Active stacks: ${stack_active_profiles}" >&2
          echo "Update ${STACK_MAP_FILE:-docs/policy/stack-map.env} or declare Stack: polyglot when intentionally crossing stacks." >&2
          exit 1
        fi

        if [[ -n "${detected_stacks//[[:space:]]/}" ]]; then
          detected_count="$(wc -w <<<"$(split_csv_to_space "$detected_stacks")" | tr -d ' ')"
          if [[ "${detected_count:-0}" -gt 1 ]]; then
            echo "Multiple stacks detected in staged files (${detected_stacks}); declare Stack: polyglot." >&2
            exit 1
          fi
          if [[ "${detected_count:-0}" -eq 1 ]] && ! csv_contains "$detected_stacks" "$stack_name"; then
            echo "Declared Stack '${stack_name}' does not match detected stack '${detected_stacks}' from staged files." >&2
            exit 1
          fi
        fi
      fi
    fi

    if ! grep -Eiq '^TestScope:[[:space:]]*[a-z, -]+$' "$msg_file"; then
      echo "Code-impacting commit requires test scope declaration." >&2
      echo "Add: 'TestScope: unit,integration' (comma-separated)." >&2
      exit 1
    fi
    test_scope_line="$(grep -Ei '^TestScope:[[:space:]]*[a-z, -]+$' "$msg_file" | sed -E 's/^TestScope:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1)"

    if ! grep -Eq '(^|[[:space:],-])(unit|integration|contract|e2e|property|mutation|security|migration|smoke)($|[[:space:],-])' <<<"$test_scope_line"; then
      echo "TestScope must include at least one supported category." >&2
      echo "Supported: unit,integration,contract,e2e,property,mutation,security,migration,smoke." >&2
      exit 1
    fi

    if [[ "$risk_level" == "medium" || "$risk_level" == "high" ]]; then
      scope_count="$(awk -F',' '{print NF}' <<<"$test_scope_line" | tr -d ' ')"
      if [[ "${scope_count:-0}" -lt 2 ]]; then
        echo "Risk ${risk_level} commit requires at least two TestScope categories." >&2
        exit 1
      fi
    fi
  fi
fi

if [[ "$risk_level" == "medium" || "$risk_level" == "high" ]]; then
  if ! grep -Eq '^Assumptions:[[:space:]]*.+$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires assumptions. Add: 'Assumptions: ...'." >&2
    exit 1
  fi

  if ! grep -Eq '^Rollback:[[:space:]]*.+$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires rollback note. Add: 'Rollback: ...'." >&2
    exit 1
  fi

  if ! grep -Eq '^ResearchInputs:[[:space:]]*.+$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires research intake declaration." >&2
    echo "Add: 'ResearchInputs: <docs/files/commands consulted before build>'." >&2
    exit 1
  fi

  if ! grep -Eq '^EvidenceScope:[[:space:]]*.+$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires evidence scope declaration." >&2
    echo "Add: 'EvidenceScope: in=<included>; out=<excluded>'." >&2
    exit 1
  fi

  if [[ "$require_self_eval" == "1" ]]; then
    if ! grep -Eiq '^SelfEval:[[:space:]]*(pass|rule-update-needed)[[:space:]]*$' "$msg_file"; then
      echo "Risk ${risk_level} commit requires self-evaluation result." >&2
      echo "Add: 'SelfEval: pass|rule-update-needed'." >&2
      exit 1
    fi

    if ! grep -Eiq '^PolicyDelta:[[:space:]]*(none|updated:.+)[[:space:]]*$' "$msg_file"; then
      echo "Risk ${risk_level} commit requires policy delta declaration." >&2
      echo "Add: 'PolicyDelta: none|updated:<paths>'." >&2
      exit 1
    fi

    self_eval_value="$(grep -Eio '^SelfEval:[[:space:]]*(pass|rule-update-needed)[[:space:]]*$' "$msg_file" | sed -E 's/^SelfEval:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1)"
    policy_delta_line="$(grep -Ei '^PolicyDelta:[[:space:]]*(none|updated:.+)[[:space:]]*$' "$msg_file" | tail -n1)"
    policy_delta_value="$(sed -E 's/^PolicyDelta:[[:space:]]*//I' <<<"$policy_delta_line" | tr '[:upper:]' '[:lower:]')"

    if [[ "$self_eval_value" == "rule-update-needed" ]]; then
      if ! grep -Eiq '^PolicyDelta:[[:space:]]*updated:.+[[:space:]]*$' "$msg_file"; then
        echo "SelfEval is rule-update-needed; PolicyDelta must list updated policy artifacts." >&2
        exit 1
      fi
      if ! grep -Eq "$policy_update_path_regex" <<<"$staged_files_list"; then
        echo "SelfEval is rule-update-needed but no policy artifacts are staged." >&2
        echo "Update rules/templates/validators/docs in the same commit." >&2
        exit 1
      fi
    fi

    if [[ "$policy_delta_value" =~ ^updated: ]] && ! grep -Eq "$policy_update_path_regex" <<<"$staged_files_list"; then
      echo "PolicyDelta declares updates, but no policy artifacts are staged." >&2
      exit 1
    fi
  fi

  if ! grep -Eiq '^WorkflowType:[[:space:]]*(feature-development|maintenance|collaboration)[[:space:]]*$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires workflow type declaration." >&2
    echo "Add: 'WorkflowType: feature-development|maintenance|collaboration'." >&2
    exit 1
  fi

  if ! grep -Eiq '^WorkflowMode:[[:space:]]*(simple|plan-build|incremental-gates)[[:space:]]*$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires workflow mode declaration." >&2
    echo "Add: 'WorkflowMode: simple|plan-build|incremental-gates'." >&2
    exit 1
  fi

  if ! grep -Eiq '^TaskState:[[:space:]]*(planned|in-progress|blocked|verify|done)[[:space:]]*$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires task lifecycle state declaration." >&2
    echo "Add: 'TaskState: planned|in-progress|blocked|verify|done'." >&2
    exit 1
  fi

  task_state_value="$(grep -Eio '^TaskState:[[:space:]]*(planned|in-progress|blocked|verify|done)[[:space:]]*$' "$msg_file" | sed -E 's/^TaskState:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1)"
  if [[ "$task_state_value" == "blocked" ]]; then
    if ! grep -Eq '^NextAction:[[:space:]]*.+$' "$msg_file"; then
      echo "TaskState is blocked; NextAction is required." >&2
      echo "Add: 'NextAction: <owner/action/date or unblock command>'." >&2
      exit 1
    fi
  fi

  if ! grep -Eiq 'FR-[0-9]+.*(met|not[[:space:]]+met)|AC-[0-9]+.*(met|not[[:space:]]+met)' "$msg_file"; then
    echo "Risk ${risk_level} commit requires a met/not met checklist line for FR/AC IDs." >&2
    echo "Example: 'FR-101: met, AC-201: met'" >&2
    exit 1
  fi

  if [[ "$require_medium_high_quality_signals" == "1" ]]; then
    if ! grep -Eq '^QualitySignals:[[:space:]]*.+$' "$msg_file"; then
      echo "Risk ${risk_level} commit requires quality signal metadata." >&2
      echo "Add: 'QualitySignals: issue_density|churn|rework|mutation_delta: <note>'." >&2
      exit 1
    fi
    if ! grep -Eiq '^QualitySignals:[[:space:]]*.*(issue_density|churn|rework|mutation_delta).*' "$msg_file"; then
      echo "QualitySignals must include one of: issue_density, churn, rework, mutation_delta." >&2
      exit 1
    fi
  fi

  if [[ "$require_review_passes" == "1" ]]; then
    if ! grep -Eq '^ReviewPasses:[[:space:]]*.+$' "$msg_file"; then
      echo "Risk ${risk_level} commit requires layered review pass declaration." >&2
      echo "Add: 'ReviewPasses: pass1-logic-security,pass2-maintainability'" >&2
      exit 1
    fi
    if ! grep -Eiq '^ReviewPasses:[[:space:]]*.*pass1-logic-security.*pass2-maintainability.*$' "$msg_file"; then
      echo "ReviewPasses must include both pass1-logic-security and pass2-maintainability." >&2
      exit 1
    fi
  fi

  if [[ "$require_review_focus" == "1" ]]; then
    if ! grep -Eiq '^ReviewFocus:[[:space:]]*(security|performance|maintainability)[[:space:]]*$' "$msg_file"; then
      echo "Risk ${risk_level} commit requires review focus declaration." >&2
      echo "Add: 'ReviewFocus: security|performance|maintainability'" >&2
      exit 1
    fi
  fi

  if [[ "$require_agent_role" == "1" ]]; then
    if ! grep -Eiq '^AgentRole:[[:space:]]*(orchestrator|implementer|verifier|reviewer|solo)[[:space:]]*$' "$msg_file"; then
      echo "Risk ${risk_level} commit requires agent role declaration." >&2
      echo "Add: 'AgentRole: orchestrator|implementer|verifier|reviewer|solo'" >&2
      exit 1
    fi
    agent_role="$(grep -Eio '^AgentRole:[[:space:]]*(orchestrator|implementer|verifier|reviewer|solo)[[:space:]]*$' "$msg_file" | sed -E 's/^AgentRole:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1)"
  fi

  if [[ "$require_stack_profile" == "1" ]]; then
    if ! grep -Eiq '^StackProfile:[[:space:]]*(node|python|go|java|dotnet|rust|php|ruby|polyglot|other)[[:space:]]*$' "$msg_file"; then
      echo "Risk ${risk_level} commit requires stack profile declaration." >&2
      echo "Add: 'StackProfile: node|python|go|java|dotnet|rust|php|ruby|polyglot|other'" >&2
      exit 1
    fi
  fi

  if [[ "$require_observability_evidence" == "1" ]]; then
    if ! grep -Eiq '^Observability:[[:space:]]*logs=(updated|unchanged),metrics=(updated|unchanged),alerts=(updated|unchanged)[[:space:]]*$' "$msg_file"; then
      echo "Risk ${risk_level} commit requires observability metadata." >&2
      echo "Add: 'Observability: logs=updated|unchanged,metrics=updated|unchanged,alerts=updated|unchanged'" >&2
      exit 1
    fi
  fi

  if ! grep -Eiq '^AgentDepth:[[:space:]]*(0|1)[[:space:]]*$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires agent depth declaration." >&2
    echo "Add: 'AgentDepth: 0|1'" >&2
    exit 1
  fi

  if ! grep -Eiq '^Delegation:[[:space:]]*(none|planner,implementer,verifier,reviewer|implementer,verifier,reviewer|planner,implementer,verifier|planner,verifier|planner,implementer|implementer,verifier|verifier,reviewer|implementer,reviewer|planner,reviewer|planner|implementer|verifier|reviewer)[[:space:]]*$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires delegation declaration." >&2
    echo "Add: 'Delegation: none|planner,implementer,verifier,reviewer'" >&2
    exit 1
  fi

  delegation_value="$(grep -Eio '^Delegation:[[:space:]]*(none|planner,implementer,verifier,reviewer|implementer,verifier,reviewer|planner,implementer,verifier|planner,verifier|planner,implementer|implementer,verifier|verifier,reviewer|implementer,reviewer|planner,reviewer|planner|implementer|verifier|reviewer)[[:space:]]*$' "$msg_file" | sed -E 's/^Delegation:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1)"

  if [[ "$agent_role" != "orchestrator" ]]; then
    if [[ "$delegation_value" != "none" ]]; then
      echo "Only orchestrator may delegate/spawn subagents. Non-orchestrator role '${agent_role}' must declare 'Delegation: none'." >&2
      exit 1
    fi
    if ! grep -Eiq '^SpawnedAgents:[[:space:]]*0[[:space:]]*$' "$msg_file"; then
      echo "Non-orchestrator role '${agent_role}' requires explicit spawn declaration." >&2
      echo "Add: 'SpawnedAgents: 0'" >&2
      exit 1
    fi

    if [[ "$agent_role" == "implementer" || "$agent_role" == "verifier" || "$agent_role" == "reviewer" ]]; then
      if ! grep -Eiq '^Invocation:[[:space:]]*(run-agent\.sh|scripts/run-agent\.sh)[[:space:]]*$' "$msg_file"; then
        echo "Subagent role '${agent_role}' must declare guarded launcher usage." >&2
        echo "Add: 'Invocation: run-agent.sh'" >&2
        exit 1
      fi

      if grep -Eiq '^[[:space:]]*\$[[:space:]]+.*\bcodex[[:space:]]+exec\b' "$msg_file"; then
        echo "Subagent role '${agent_role}' cannot use direct 'codex exec' in verification commands." >&2
        echo "Use guarded launcher evidence (Invocation: run-agent.sh)." >&2
        exit 1
      fi
    fi
  fi

  if [[ "$agent_role" == "orchestrator" && "$delegation_value" != "none" ]]; then
    if ! grep -Eiq '^SpawnBudget:[[:space:]]*[0-9]+[[:space:]]*$' "$msg_file"; then
      echo "Orchestrator with delegation requires spawn budget declaration." >&2
      echo "Add: 'SpawnBudget: <n>'" >&2
      exit 1
    fi
    if ! grep -Eiq '^MaxSpawnDepth:[[:space:]]*1[[:space:]]*$' "$msg_file"; then
      echo "Orchestrator with delegation must enforce bounded depth." >&2
      echo "Add: 'MaxSpawnDepth: 1'" >&2
      exit 1
    fi
  fi
fi

review_focus="$(grep -Eio '^ReviewFocus:[[:space:]]*(security|performance|maintainability)[[:space:]]*$' "$msg_file" | sed -E 's/^ReviewFocus:[[:space:]]*//I' | tr '[:upper:]' '[:lower:]' | tail -n1 || true)"

requires_perf_evidence=0
if [[ "$require_performance_evidence" == "1" && "$review_focus" == "performance" ]]; then
  requires_perf_evidence=1
fi
if [[ "$require_high_risk_performance_evidence" == "1" && "$risk_level" == "high" ]]; then
  requires_perf_evidence=1
fi

if [[ "$requires_perf_evidence" == "1" ]]; then
  if ! grep -Eiq '^PerfBaseline:[[:space:]]*.+$' "$msg_file"; then
    echo "Performance evidence required: missing PerfBaseline." >&2
    exit 1
  fi
  if ! grep -Eiq '^PerfBudget:[[:space:]]*.+$' "$msg_file"; then
    echo "Performance evidence required: missing PerfBudget." >&2
    exit 1
  fi
  if ! grep -Eiq '^PerfProfile:[[:space:]]*.+$' "$msg_file"; then
    echo "Performance evidence required: missing PerfProfile." >&2
    exit 1
  fi
  if ! grep -Eiq '^PerfBench:[[:space:]]*.+$' "$msg_file"; then
    echo "Performance evidence required: missing PerfBench." >&2
    exit 1
  fi
fi

requires_maintainability_evidence=0
if [[ "$require_maintainability_evidence" == "1" && "$review_focus" == "maintainability" ]]; then
  requires_maintainability_evidence=1
fi

if [[ "$requires_maintainability_evidence" == "1" ]]; then
  if ! grep -Eiq '^DuplicationCheck:[[:space:]]*(pass|fail|not-applicable)[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
    echo "Maintainability evidence required: missing/invalid DuplicationCheck." >&2
    echo "Add: 'DuplicationCheck: pass|fail|not-applicable - <delta or note>'" >&2
    exit 1
  fi
  if ! grep -Eiq '^SmellCheck:[[:space:]]*(pass|fail|not-applicable)[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
    echo "Maintainability evidence required: missing/invalid SmellCheck." >&2
    echo "Add: 'SmellCheck: pass|fail|not-applicable - <tool/result>'" >&2
    exit 1
  fi
  if ! grep -Eiq '^MaintainabilityChecklist:[[:space:]]*(docs/maintainability/[^[:space:]]+\.md|not-applicable)[[:space:]]*$' "$msg_file"; then
    echo "Maintainability evidence required: missing/invalid MaintainabilityChecklist." >&2
    echo "Add: 'MaintainabilityChecklist: docs/maintainability/maintainability-checklist-<topic>.md|not-applicable'" >&2
    exit 1
  fi
  checklist_path="$(grep -Eio '^MaintainabilityChecklist:[[:space:]]*docs/maintainability/[^[:space:]]+\.md[[:space:]]*$' "$msg_file" | sed -E 's/^MaintainabilityChecklist:[[:space:]]*//I' | tail -n1)"
  if [[ -n "${checklist_path:-}" && ! -f "$checklist_path" ]]; then
    echo "MaintainabilityChecklist file does not exist: ${checklist_path}" >&2
    exit 1
  fi
fi

if [[ "$require_data_handling_declaration" == "1" && ( "$change_type" == "security" || "$risk_level" == "high" ) ]]; then
  if ! grep -Eiq '^DataHandling:[[:space:]]*pii=(none|redacted|encrypted|not-applicable),retention=[^,]+,logs=(redacted|not-applicable)[[:space:]]*$' "$msg_file"; then
    echo "Security/high-risk commit requires data handling declaration." >&2
    echo "Add: 'DataHandling: pii=none|redacted|encrypted|not-applicable,retention=<impact>,logs=redacted|not-applicable'" >&2
    exit 1
  fi
fi

# No-new-facts declaration for non-trivial implementation risk.
if [[ "$risk_level" == "medium" || "$risk_level" == "high" ]]; then
  if ! grep -Eiq '^NoNewFacts:[[:space:]]*yes[[:space:]]*$' "$msg_file"; then
    echo "Risk ${risk_level} commit requires no-new-facts confirmation. Add: 'NoNewFacts: yes'." >&2
    exit 1
  fi
fi

# Bugfixes require MRE and independent behavioral validation.
if [[ "$change_type" == "bugfix" ]]; then
  if ! grep -Eq '^MRE:[[:space:]]*.+$' "$msg_file"; then
    echo "Bugfix commit requires minimal repro. Add: 'MRE: <repro command/steps>'." >&2
    exit 1
  fi
  if ! grep -Eq '^Before:[[:space:]]*.+$' "$msg_file"; then
    echo "Bugfix commit requires failing evidence. Add: 'Before: <failing evidence>'." >&2
    exit 1
  fi
  if ! grep -Eq '^After:[[:space:]]*.+$' "$msg_file"; then
    echo "Bugfix commit requires post-fix evidence. Add: 'After: <passing evidence>'." >&2
    exit 1
  fi
  if ! grep -Eiq '^IndependentCheck:[[:space:]]*.+$' "$msg_file"; then
    echo "Bugfix commit requires independent validation. Add: 'IndependentCheck: <counterexample|property|differential|regression>'." >&2
    exit 1
  fi
  if ! grep -Eiq '^DebugBrief:[[:space:]]*(docs/debug-brief\.md|docs/handoffs/handoff-.*\.md)[[:space:]]*$' "$msg_file"; then
    echo "Bugfix commit requires debug artifact reference. Add: 'DebugBrief: docs/debug-brief.md' or 'docs/handoffs/handoff-<name>.md'." >&2
    exit 1
  fi
fi

# Feature commits must point to planning artifacts.
if [[ "$change_type" == "feature" ]]; then
  if ! grep -Eiq '^Plan:[[:space:]]*docs/plans/[^[:space:]]+\.md[[:space:]]*$' "$msg_file"; then
    echo "Feature commit requires plan reference. Add: 'Plan: docs/plans/<file>.md'." >&2
    exit 1
  fi
  if ! grep -Eiq '^TaskBrief:[[:space:]]*(docs/task-briefs/[^[:space:]]+\.md|docs/templates/task-brief\.md|[^[:space:]]*task-brief[^[:space:]]*\.md)[[:space:]]*$' "$msg_file"; then
    echo "Feature commit requires task brief reference. Add: 'TaskBrief: docs/task-briefs/<file>.md'." >&2
    exit 1
  fi
fi

# Refactor commits must declare characterization strategy.
if [[ "$change_type" == "refactor" ]]; then
  if ! grep -Eiq '^Characterization:[[:space:]]*(added|existing)[[:space:]]*$' "$msg_file"; then
    echo "Refactor commit requires characterization declaration. Add: 'Characterization: added|existing'." >&2
    exit 1
  fi
fi

# High-risk or explicitly large-change commits require a phase checkpoint reference.
if [[ "$risk_level" == "high" ]] || grep -Eiq '^Override:[[:space:]]*large-change[[:space:]]*$' "$msg_file"; then
  if ! grep -Eiq '^PhaseCheckpoint:[[:space:]]*docs/handoffs/handoff-.*\.md[[:space:]]*$' "$msg_file"; then
    echo "High-risk or large-change commit requires phase checkpoint reference." >&2
    echo "Add: 'PhaseCheckpoint: docs/handoffs/handoff-<phase>.md'" >&2
    exit 1
  fi

  if [[ "$require_high_risk_threat_model" == "1" ]]; then
    if ! grep -Eiq '^ThreatModel:[[:space:]]*(stride|owasp|both)[[:space:]]*$' "$msg_file"; then
      echo "High-risk or large-change commit requires threat model declaration." >&2
      echo "Add: 'ThreatModel: STRIDE|OWASP|both'" >&2
      exit 1
    fi
  fi

  if [[ "$require_high_risk_rollback_rehearsal" == "1" ]]; then
    if ! grep -Eiq '^RollbackRehearsal:[[:space:]]*(pass|simulated|not-applicable)[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
      echo "High-risk or large-change commit requires rollback rehearsal evidence." >&2
      echo "Add: 'RollbackRehearsal: pass|simulated|not-applicable - <steps/outcome>'" >&2
      exit 1
    fi
  fi

  if ! grep -Eiq '^MitigationPlan:[[:space:]]*(rollback|disable-path|capacity)[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
    echo "High-risk or large-change commit requires mitigation-first plan." >&2
    echo "Add: 'MitigationPlan: rollback|disable-path|capacity - <trigger>'" >&2
    exit 1
  fi

  if [[ "$require_release_safety_fields" == "1" ]]; then
    if ! grep -Eiq '^ReleaseStrategy:[[:space:]]*(canary|staged|full|not-applicable)[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
      echo "High-risk or large-change commit requires release strategy metadata." >&2
      echo "Add: 'ReleaseStrategy: canary|staged|full|not-applicable - <scope/trigger>'" >&2
      exit 1
    fi
    if ! grep -Eiq '^Runbook:[[:space:]]*(docs/runbooks/[^[:space:]]+\.md|not-applicable)[[:space:]]*$' "$msg_file"; then
      echo "High-risk or large-change commit requires runbook metadata." >&2
      echo "Add: 'Runbook: docs/runbooks/<name>.md|not-applicable'" >&2
      exit 1
    fi
    runbook_path="$(grep -Eio '^Runbook:[[:space:]]*docs/runbooks/[^[:space:]]+\.md[[:space:]]*$' "$msg_file" | sed -E 's/^Runbook:[[:space:]]*//I' | tail -n1)"
    if [[ -n "${runbook_path:-}" && ! -f "$runbook_path" ]]; then
      echo "Runbook file does not exist: ${runbook_path}" >&2
      exit 1
    fi
  fi

  if [[ "$require_high_risk_second_review" == "1" ]]; then
    if ! grep -Eiq '^SecondReview:[[:space:]]*yes[[:space:]]*$' "$msg_file"; then
      echo "High-risk or large-change commit requires second review declaration." >&2
      echo "Add: 'SecondReview: yes'" >&2
      exit 1
    fi
  fi

  if [[ "$require_security_signoff" == "1" ]]; then
    if ! grep -Eiq '^SecuritySignoff:[[:space:]]*human\+tooling[[:space:]]*$' "$msg_file"; then
      echo "High-risk or large-change commit requires security signoff metadata." >&2
      echo "Add: 'SecuritySignoff: human+tooling'" >&2
      exit 1
    fi
  fi

  if [[ "$require_security_scans_declaration" == "1" ]]; then
    if ! grep -Eiq '^SecurityScans:[[:space:]]*.+$' "$msg_file"; then
      echo "High-risk or large-change commit requires SecurityScans declaration." >&2
      echo "Add: 'SecurityScans: sast=...,dependency=...,sbom=...,secrets=...,dast=...'" >&2
      exit 1
    fi
    if ! grep -Eiq '^SecurityScans:[[:space:]]*.*sast=(pass|fail|not-applicable).*dependency=(pass|fail|not-applicable).*sbom=(pass|fail|not-applicable).*secrets=(pass|fail|not-applicable).*dast=(pass|fail|not-applicable).*$' "$msg_file"; then
      echo "SecurityScans must include sast, dependency, sbom, secrets, and dast key/value statuses." >&2
      exit 1
    fi
  fi

  if [[ "$require_high_risk_review_packet" == "1" ]]; then
    if ! grep -Eq '^ReviewPacket:[[:space:]]*.+$' "$msg_file"; then
      echo "High-risk or large-change commit requires review packet declaration." >&2
      echo "Add: 'ReviewPacket: assumptions,threat-model,test-plan,rollback-plan'" >&2
      exit 1
    fi
    if ! grep -Eiq '^ReviewPacket:[[:space:]]*.*assumptions.*threat-model.*test-plan.*rollback-plan.*$' "$msg_file"; then
      echo "ReviewPacket must include assumptions, threat-model, test-plan, and rollback-plan." >&2
      exit 1
    fi
  fi
fi

# Security changes must declare untrusted input boundary handling.
if [[ "$require_security_trust_boundary" == "1" && "$change_type" == "security" ]]; then
  if ! grep -Eiq '^UntrustedInputBoundary:[[:space:]]*(validated|not-applicable)[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
    echo "Security commit requires untrusted input boundary declaration." >&2
    echo "Add: 'UntrustedInputBoundary: validated|not-applicable - <allowlist/boundary>'" >&2
    exit 1
  fi
fi

if [[ "$require_security_signoff" == "1" && "$change_type" == "security" ]]; then
  if ! grep -Eiq '^SecuritySignoff:[[:space:]]*human\+tooling[[:space:]]*$' "$msg_file"; then
    echo "Security commit requires explicit human+tooling security signoff metadata." >&2
    echo "Add: 'SecuritySignoff: human+tooling'" >&2
    exit 1
  fi
fi

if [[ "$require_security_scans_declaration" == "1" && "$change_type" == "security" ]]; then
  if ! grep -Eiq '^SecurityScans:[[:space:]]*.+$' "$msg_file"; then
    echo "Security commit requires SecurityScans declaration." >&2
    echo "Add: 'SecurityScans: sast=...,dependency=...,sbom=...,secrets=...,dast=...'" >&2
    exit 1
  fi
  if ! grep -Eiq '^SecurityScans:[[:space:]]*.*sast=(pass|fail|not-applicable).*dependency=(pass|fail|not-applicable).*sbom=(pass|fail|not-applicable).*secrets=(pass|fail|not-applicable).*dast=(pass|fail|not-applicable).*$' "$msg_file"; then
    echo "SecurityScans must include sast, dependency, sbom, secrets, and dast key/value statuses." >&2
    exit 1
  fi
fi

if [[ "$require_security_checklist" == "1" && "$change_type" == "security" ]]; then
  if ! grep -Eiq '^SecurityChecklist:[[:space:]]*docs/security/[^[:space:]]+\.md[[:space:]]*$' "$msg_file"; then
    echo "Security commit requires checklist artifact reference." >&2
    echo "Add: 'SecurityChecklist: docs/security/security-checklist-<topic>.md'" >&2
    exit 1
  fi

  checklist_path="$(grep -Eio '^SecurityChecklist:[[:space:]]*docs/security/[^[:space:]]+\.md[[:space:]]*$' "$msg_file" | sed -E 's/^SecurityChecklist:[[:space:]]*//I' | tail -n1)"
  if [[ -n "${checklist_path:-}" && ! -f "$checklist_path" ]]; then
    echo "SecurityChecklist file does not exist: ${checklist_path}" >&2
    exit 1
  fi
fi

# Bugfix escalations beyond timebox must be explicit.
if [[ "$change_type" == "bugfix" ]] && grep -Eq '^EscalationAfterMins:[[:space:]]*[0-9]+[[:space:]]*$' "$msg_file"; then
  escalation_mins="$(grep -Eio '^EscalationAfterMins:[[:space:]]*[0-9]+[[:space:]]*$' "$msg_file" | grep -Eo '[0-9]+' | tail -n1)"
  if [[ -n "${escalation_mins:-}" ]] && (( escalation_mins < 30 )); then
    echo "EscalationAfterMins should be >= 30." >&2
    exit 1
  fi
  if ! grep -Eiq '^EscalationPath:[[:space:]]*(rollback|restart|second-review|mre-narrow)[[:space:]]*$' "$msg_file"; then
    echo "EscalationAfterMins requires escalation path." >&2
    echo "Add: 'EscalationPath: rollback|restart|second-review|mre-narrow'" >&2
    exit 1
  fi
fi

# Policy exceptions must include complete metadata.
if [[ "$enforce_policy_exception_fields" == "1" ]] && grep -Eiq '^PolicyException:[[:space:]]*yes[[:space:]]*$' "$msg_file"; then
  if ! grep -Eq '^ExceptionOwner:[[:space:]]*.+$' "$msg_file"; then
    echo "PolicyException requires ExceptionOwner." >&2
    exit 1
  fi
  if ! grep -Eq '^ExceptionReason:[[:space:]]*.+$' "$msg_file"; then
    echo "PolicyException requires ExceptionReason." >&2
    exit 1
  fi
  if ! grep -Eiq "^ExceptionIssue:[[:space:]]*(#([0-9]+)|${issue_url_regex})[[:space:]]*$" "$msg_file"; then
    echo "PolicyException requires ExceptionIssue as #id or GitHub issue URL." >&2
    exit 1
  fi
  if ! grep -Eq '^ExceptionExpires:[[:space:]]*[0-9]{4}-[0-9]{2}-[0-9]{2}[[:space:]]*$' "$msg_file"; then
    echo "PolicyException requires ExceptionExpires in YYYY-MM-DD format." >&2
    exit 1
  fi
  if [[ "$reject_expired_policy_dates" == "1" ]]; then
    exception_expires="$(grep -Eio '^ExceptionExpires:[[:space:]]*[0-9]{4}-[0-9]{2}-[0-9]{2}[[:space:]]*$' "$msg_file" | grep -Eo '[0-9]{4}-[0-9]{2}-[0-9]{2}' | tail -n1)"
    if [[ -n "${exception_expires:-}" && "$exception_expires" < "$today_ymd" ]]; then
      echo "PolicyException date is expired (${exception_expires} < ${today_ymd}). Renew or remove exception." >&2
      exit 1
    fi
  fi
  if ! grep -Eq '^ExceptionFollowup:[[:space:]]*.+$' "$msg_file"; then
    echo "PolicyException requires ExceptionFollowup." >&2
    exit 1
  fi
fi

# Flaky test quarantine metadata must be complete when declared.
if grep -Eq '^FlakyTest:[[:space:]]*.+$' "$msg_file"; then
  if ! grep -Eq '^FlakyOwner:[[:space:]]*.+$' "$msg_file"; then
    echo "FlakyTest requires FlakyOwner." >&2
    exit 1
  fi
  if ! grep -Eiq "^FlakyIssue:[[:space:]]*(#([0-9]+)|${issue_url_regex})[[:space:]]*$" "$msg_file"; then
    echo "FlakyTest requires FlakyIssue as #id or GitHub issue URL." >&2
    exit 1
  fi
  if ! grep -Eq '^FlakyBy:[[:space:]]*[0-9]{4}-[0-9]{2}-[0-9]{2}[[:space:]]*$' "$msg_file"; then
    echo "FlakyTest requires FlakyBy in YYYY-MM-DD format." >&2
    exit 1
  fi
  if [[ "$reject_expired_policy_dates" == "1" ]]; then
    flaky_by="$(grep -Eio '^FlakyBy:[[:space:]]*[0-9]{4}-[0-9]{2}-[0-9]{2}[[:space:]]*$' "$msg_file" | grep -Eo '[0-9]{4}-[0-9]{2}-[0-9]{2}' | tail -n1)"
    if [[ -n "${flaky_by:-}" && "$flaky_by" < "$today_ymd" ]]; then
      echo "Flaky quarantine date is expired (${flaky_by} < ${today_ymd}). Resolve or renew with new date." >&2
      exit 1
    fi
  fi
fi

if [[ "$enforce_test_contract" == "1" && "$enforce_stack_cmd_hints" == "1" ]]; then
  if [[ "$change_type" =~ ^(feature|bugfix|refactor|security)$ ]]; then
    stack_cmd_pattern=""
    case "$stack_name" in
      node) stack_cmd_pattern='npm|pnpm|yarn|jest|vitest|playwright|cypress' ;;
      python) stack_cmd_pattern='pytest|tox|nox|uv run' ;;
      go) stack_cmd_pattern='go test' ;;
      java) stack_cmd_pattern='mvn|gradle|./gradlew' ;;
      dotnet) stack_cmd_pattern='dotnet test' ;;
      rust) stack_cmd_pattern='cargo test' ;;
      php) stack_cmd_pattern='phpunit|pest' ;;
      ruby) stack_cmd_pattern='rspec|bundle exec rspec' ;;
      polyglot|other) stack_cmd_pattern='' ;;
    esac

    if [[ -n "$stack_cmd_pattern" ]]; then
      if ! grep -Eiq '^[[:space:]]*\$[[:space:]]+.*('"$stack_cmd_pattern"').*$' "$msg_file"; then
        echo "Verification commands do not match declared Stack: ${stack_name}." >&2
        echo "Add at least one command consistent with the stack toolchain." >&2
        exit 1
      fi
    fi
  fi
fi

# Non-trivial commits must include requirement traceability IDs.
# A commit is treated as non-trivial if staged changes touch >1 file or >80 changed lines.
non_trivial_files="${COMMIT_NON_TRIVIAL_CHANGED_FILES:-1}"
non_trivial_lines="${COMMIT_NON_TRIVIAL_CHANGED_LINES:-80}"
staged_files="$(git diff --cached --name-only | wc -l | tr -d ' ')"
staged_lines="$(git diff --cached --numstat | awk '{a+=$1; d+=$2} END {print a+d+0}')"

if [[ "$require_dependency_check" == "1" ]]; then
  if grep -Eq "$dependency_manifest_regex" <<<"$staged_files_list"; then
    if ! grep -Eq '^DependencyCheck:[[:space:]]*.+$' "$msg_file"; then
      echo "Dependency manifest change requires dependency verification metadata." >&2
      echo "Add: 'DependencyCheck: registry-verified,pinned,maintained - <evidence>'" >&2
      exit 1
    fi
    if ! grep -Eiq '^DependencyCheck:[[:space:]]*.*registry-verified.*pinned.*maintained.*$' "$msg_file"; then
      echo "DependencyCheck must include registry-verified, pinned, and maintained markers." >&2
      exit 1
    fi
  fi
fi

if [[ "$require_dependency_license_check" == "1" ]]; then
  if grep -Eq "$dependency_manifest_regex" <<<"$staged_files_list"; then
    if ! grep -Eiq '^DependencyLicenseCheck:[[:space:]]*(pass|fail|not-applicable)[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
      echo "Dependency manifest change requires license/compliance metadata." >&2
      echo "Add: 'DependencyLicenseCheck: pass|fail|not-applicable - <license/compliance note>'" >&2
      exit 1
    fi
  fi
fi

if [[ "$require_compatibility_fields" == "1" ]]; then
  if grep -Eiq "$contract_compat_required_path_regex" <<<"$staged_files_list"; then
    if ! grep -Eiq '^Compatibility:[[:space:]]*(backward-compatible|breaking-change)[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
      echo "Contract/interface change requires compatibility declaration." >&2
      echo "Add: 'Compatibility: backward-compatible|breaking-change - <impact>'" >&2
      exit 1
    fi
    if ! grep -Eiq '^Deprecation:[[:space:]]*(none|date=[0-9]{4}-[0-9]{2}-[0-9]{2}|not-applicable)[[:space:]]*$' "$msg_file"; then
      echo "Contract/interface change requires deprecation declaration." >&2
      echo "Add: 'Deprecation: none|date=YYYY-MM-DD|not-applicable'" >&2
      exit 1
    fi
  fi
fi

if [[ "$change_type" == "bugfix" ]] && (( staged_files >= bugfix_high_context_file_threshold )); then
  if ! grep -Eiq '^ContextReduction:[[:space:]]*yes[[:space:]]*-[[:space:]]+.+$' "$msg_file"; then
    echo "High-context bugfix (${staged_files} files) requires context-reduction strategy." >&2
    echo "Add: 'ContextReduction: yes - <2-6 files per slice strategy>'" >&2
    exit 1
  fi
fi

if (( staged_files > non_trivial_files || staged_lines > non_trivial_lines )); then
  if ! grep -Eq '^Traceability:[[:space:]]*.+$' "$msg_file"; then
    echo "Non-trivial commit requires traceability. Add: 'Traceability: FR-###, AC-###'." >&2
    exit 1
  fi

  trace_line="$(grep -Ei '^Traceability:[[:space:]]*.+$' "$msg_file" | tail -n1)"
  if ! grep -Eq 'FR-[0-9]+' <<<"$trace_line" || ! grep -Eq 'AC-[0-9]+' <<<"$trace_line"; then
    echo "Traceability line must include both FR-### and AC-### IDs." >&2
    exit 1
  fi
fi

exit 0
